const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const errorPayload = $json;
const healthResponse = await fetch(`${runnerBase}/jobs`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ action: 'service_health_report', mode: 'sync', args: [] }),
});
const rawHealth = await healthResponse.text();
const healthResult = rawHealth ? JSON.parse(rawHealth) : null;
const reportRelativePath = `error-recovery/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Error Recovery Agent',
  '',
  `Generated: ${new Date().toISOString()}`,
  '',
  '## Error Payload',
  '',
  '```json',
  JSON.stringify(errorPayload, null, 2),
  '```',
  '',
  '## Health Result',
  '',
  healthResult ? '```json\n' + JSON.stringify(healthResult, null, 2) + '\n```' : 'Health check unavailable.',
].join('\n');
const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);
return [{ json: { reportRelativePath, healthResult } }];
